vertexShader:
attribute float aLife; attribute float aSeed; varying float vA;
#include <fog_pars_vertex>
void main(){ vec4 mvPosition = modelViewMatrix * vec4(position, 1.0); gl_Position = projectionMatrix * mvPosition; gl_PointSize = (2.0 + aLife * 7.0) * 220.0 / -mvPosition.z; vA = sin(aLife * 3.14159) * 0.16;
#include <fog_vertex>
}

fragmentShader:
uniform sampler2D map; varying float vA;
#include <fog_pars_fragment>
void main(){ float a = texture2D(map, gl_PointCoord).a * vA; gl_FragColor = vec4(vec3(0.55, 0.58, 0.62), a);
#include <fog_fragment>
}
